def checkString(s: str) -> bool:
    # Once we've seen a 'b', any following 'a' is an invalid case
    found_b = False
    for c in s:
        if c == 'b':
            found_b = True
        elif c == 'a':
            if found_b:
                # Found 'a' after previously seeing 'b', invalid
                return False
    return True
